#!/usr/bin/env python3
"""Forward Codex skill searches to LihFolk's existing vault search engine."""

# Generated by LihFolk V2 Codex integration.
# Adapted from LihFolk Vault V2 by LihFolk; CC BY 4.0: https://creativecommons.org/licenses/by/4.0/.

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from pathlib import Path


def find_vault_root(explicit: str | None = None) -> Path | None:
    if explicit:
        candidates = [Path(explicit).expanduser()]
    elif os.environ.get("LIHFOLK_VAULT_ROOT"):
        candidates = [Path(os.environ["LIHFOLK_VAULT_ROOT"]).expanduser()]
    else:
        candidates = []
        for current in (Path.cwd(), *Path.cwd().parents):
            config = current / ".lihfolk-codex.json"
            if config.is_file():
                try:
                    data = json.loads(config.read_text(encoding="utf-8"))
                    value = data.get("vault_root") if isinstance(data, dict) else None
                    if isinstance(value, str) and value.strip():
                        configured = Path(value).expanduser()
                        candidates.append(configured if configured.is_absolute() else config.parent / configured)
                        break
                except (OSError, json.JSONDecodeError):
                    print(f"LihFolk configuration is unreadable: {config}", file=sys.stderr)
                    return None
        # When the skill is in the LihFolk checkout, its repository root is a stable fallback.
        candidates.append(Path(__file__).resolve().parents[4])
        candidates.extend(Path.cwd().parents)

    for candidate in candidates:
        root = candidate.resolve()
        if (root / "LihFolk Vault V2" / "_tools" / "vault.py").is_file() or (root / "_tools" / "vault.py").is_file():
            return root
    return None


def find_search_tool(root: Path) -> Path:
    candidates = (root / "LihFolk Vault V2" / "_tools" / "vault.py", root / "_tools" / "vault.py")
    for candidate in candidates:
        if candidate.is_file():
            return candidate
    raise FileNotFoundError(f"No vault.py search engine under {root}")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("--vault-root")
    options, forwarded = parser.parse_known_args(argv)
    root = find_vault_root(options.vault_root)
    if root is None:
        print(
            "LihFolk Vault V2 was not found. Install the integration with scripts/install_codex.py, "
            "set LIHFOLK_VAULT_ROOT, or pass --vault-root.",
            file=sys.stderr,
        )
        return 2
    try:
        search_tool = find_search_tool(root)
    except FileNotFoundError as exc:
        print(f"LihFolk source files are missing: {exc}", file=sys.stderr)
        return 2
    if not forwarded:
        print("Provide a Roblox query, or pass a vault.py option such as --read, --sections, or --api.", file=sys.stderr)
        return 2

    try:
        result = subprocess.run(
            [sys.executable, str(search_tool), *forwarded],
            cwd=Path.cwd(),
            text=True,
            encoding="utf-8",
            errors="replace",
            check=False,
        )
    except OSError as exc:
        print(f"Could not start the LihFolk search engine: {exc}", file=sys.stderr)
        return 2
    return result.returncode


if __name__ == "__main__":
    raise SystemExit(main())
